CREATE DATABASE IF NOT EXISTS tinkuy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tinkuy;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('buyer','seller') NOT NULL DEFAULT 'buyer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stores(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,region VARCHAR(60) NOT NULL,description TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,store_id INT NOT NULL,category_id INT NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 1,image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(store_id) REFERENCES stores(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,total DECIMAL(10,2) NOT NULL,address VARCHAR(200) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,store_id INT NOT NULL,qty INT NOT NULL,price DECIMAL(10,2) NOT NULL,status ENUM('pendiente','enviado','entregado') NOT NULL DEFAULT 'pendiente',FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,user_id INT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(400),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,user_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
